        SwingUtilities.invokeLater(new Runnable() {
            @Override
            public void run() {
                // Tab-completion
                if (ke.getKeyCode() == KeyEvent.VK_TAB && ke.getModifiers() == 0) {
                    if (autoCompleter != null) {
                        final int caretPos = msgTF.getCaretPosition();
                        final String orgText = msgTF.getText();
