        {
            DateTime aTime = DateTime.Now;
            int count = 0;
            List<Item> itemtodo = new List<Item>();
            foreach (Item itemremove in World.Items.Values)
            {
                if (itemremove is IntelliSpawner && ((itemremove.X >= x1 && itemremove.X <= x2) && (itemremove.Y >= y1 && itemremove.Y <= y2) && itemremove.Map == from.Map))
                {
                    itemtodo.Add(itemremove);
                    count += 1;
                }
            }
            GenericRemove(itemtodo, count, aTime);
        }
