                        continue;
                    }
                    if (graph.isAdjacentTo(a, c)) {
                        continue;
                    }
                    boolean found = foundCollider(dag, a, b, c);
                    if (found) {
                        if (verbose) {
                            System.out.println("Orienting collider " + a + "*->" + b + "<-*" + c);
                        }
                        graph.setEndpoint(a, b, Endpoint.ARROW);
                        graph.setEndpoint(c, b, Endpoint.ARROW);
                    }
                }
            }
        }
    }
