            catch (Exception)
            {
                return false;
            }
        }
        public Boolean isConfigured()
        {
            if (File.Exists(CONFIGPATH))
            {
                String[] strConfig = File.ReadAllLines(CONFIGPATH);
                Boolean found = false;
                for (int i = 0; i < strConfig.Length; i++)
                {
                    if (strConfig[i].Contains("x.x.x.x"))
                    {
                        found = true;
                        break;
                    }
                }
                return !found;
            }
            return false;
        }
